<?php

namespace App\Contract;

use InvalidArgumentException;

/**
 * The six record types iws reads, and the fields each returns.
 *
 * This is the contract (openapi.yaml says the same thing). Your SQL must
 * return a column named after every field here; you do not edit this file.
 */
final class Types
{
    public const VITAL_CODES = ['heart_rate', 'respiratory_rate', 'body_temperature', 'systolic_bp', 'diastolic_bp', 'spo2'];

    /** @return array<string, array{key: string, fields: list<Field>}> */
    public static function all(): array
    {
        $s = fn (string $name, bool $required = false) => new Field($name, 'string', $required);
        $t = fn (string $name, bool $required = false) => new Field($name, 'datetime', $required);
        $e = fn (string $name, array $values, bool $required = false) => new Field($name, 'enum', $required, $values);

        return [
            'patients' => ['key' => 'patient_key', 'fields' => [
                $s('patient_key', true), $s('nik'), $s('name', true),
                $e('gender', ['male', 'female', 'other', 'unknown']),
                new Field('birth_date', 'date'), $s('address'), $s('phone'),
            ]],
            'visits' => ['key' => 'visit_key', 'fields' => [
                $s('visit_key', true), $s('patient_key', true), $s('practitioner_key'), $s('location_key'),
                $e('class', ['ambulatory', 'emergency', 'inpatient'], true),
                $e('status', ['in-progress', 'finished', 'cancelled'], true),
                $t('admitted_at', true), $t('discharged_at'),
                new Field('diagnosis_keys', 'list'),
            ]],
            'practitioners' => ['key' => 'practitioner_key', 'fields' => [
                $s('practitioner_key', true), $s('nik'), $s('name', true),
            ]],
            'locations' => ['key' => 'location_key', 'fields' => [
                $s('location_key', true), $s('name', true),
            ]],
            'observations' => ['key' => 'observation_key', 'fields' => [
                $s('observation_key', true), $s('visit_key', true), $s('patient_key', true),
                $e('category', ['vital-signs', 'laboratory', 'exam', 'procedure', 'social-history'], true),
                $s('name', true), $s('loinc'), $s('local_code'), $s('value', true), $s('unit'), $s('reference_range'),
                $e('flag', ['N', 'H', 'L', 'A']),
                $t('effective_at', true), $t('issued_at'),
            ]],
            'conditions' => ['key' => 'condition_key', 'fields' => [
                $s('condition_key', true), $s('visit_key', true), $s('patient_key', true),
                $s('icd10', true), $s('name'), $t('recorded_at', true),
            ]],
        ];
    }

    /** @return array{key: string, fields: list<Field>} */
    public static function get(string $type): array
    {
        return self::all()[$type] ?? throw new InvalidArgumentException("unknown record type '$type'");
    }

    public static function exists(string $type): bool
    {
        return array_key_exists($type, self::all());
    }
}
